// Approach A: one component configured via a growing prop list.
// Every new use case becomes another prop and another internal branch.
function InfoPanel({ title, message, showIcon, iconType, showCloseButton, onClose, footerText }) {
  return (
    <div className="panel">
      {showIcon && <Icon type={iconType} />}
      <h3>{title}</h3>
      <p>{message}</p>
      {showCloseButton && <button onClick={onClose}>Close</button>}
      {footerText && <footer>{footerText}</footer>}
    </div>
  );
}

// Approach B: composition -- Panel only owns the chrome, the caller
// supplies the content by nesting whatever JSX it actually needs.
function Panel({ children }) {
  return <div className="panel">{children}</div>;
}

// Usage: the caller assembles exactly what it needs, no unused
// props to figure out or skip, and no changes to Panel required.
<Panel>
  <Icon type="warning" />
  <h3>Storage almost full</h3>
  <p>You're using 95% of your plan's storage.</p>
  <button onClick={handleClose}>Close</button>
</Panel>

// BEFORE: each sibling keeps its own copy of "query" -- they can drift apart.
function SearchBox() {
  const [query, setQuery] = useState("");
  return <input value={query} onChange={(e) => setQuery(e.target.value)} />;
}

function ResultsList() {
  // ResultsList has no way to know what SearchBox's query currently is --
  // this is a second, entirely disconnected copy.
  const [query, setQuery] = useState("");
  const results = allItems.filter((item) => item.includes(query));
  return <ul>{results.map((r) => <li key={r}>{r}</li>)}</ul>;
}

// AFTER: the closest common parent owns the one shared value.
function SearchPage() {
  const [query, setQuery] = useState("");

  return (
    <>
      <SearchBox query={query} onQueryChange={setQuery} />
      <ResultsList query={query} />
    </>
  );
}

function SearchBox({ query, onQueryChange }) {
  return <input value={query} onChange={(e) => onQueryChange(e.target.value)} />;
}

