// Traditional anchor tag: clicking triggers a full page reload,
// a fresh request to the server, and a brand-new HTML document.
<a href="/dashboard">Dashboard</a>

// React Router's Link: renders a real <a> for accessibility and
// right-click behavior, but intercepts a plain click, updates the
// URL, and swaps components -- no server round-trip, no full reload.
import { Link } from "react-router-dom";

<Link to="/dashboard">Dashboard</Link>

import { BrowserRouter, Routes, Route, useParams } from "react-router-dom";

function UserProfile() {
  const { id } = useParams(); // always a string, e.g. "42"
  return <h1>Profile for user #{id}</h1>;
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/users/:id" element={<UserProfile />} />
      </Routes>
    </BrowserRouter>
  );
}

