function ProductPage({ productId }) {
  // Client state: purely UI, lives only here, no "true" copy elsewhere.
  const [isDescriptionExpanded, setIsDescriptionExpanded] = useState(false);

  // Server state: really lives in a database; this is a cached, fetched copy.
  const [product, setProduct] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isCurrent = true;
    setIsLoading(true);

    fetchProduct(productId)
      .then((data) => {
        if (isCurrent) {
          setProduct(data);
          setError(null);
        }
      })
      .catch((err) => {
        if (isCurrent) setError(err);
      })
      .finally(() => {
        if (isCurrent) setIsLoading(false);
      });

    return () => {
      isCurrent = false;
    };
  }, [productId]);

  // ...render logic omitted for brevity
}

// A single context holding fast-changing state, read widely across the tree.
const CursorContext = createContext();

function App() {
  const [cursorPosition, setCursorPosition] = useState({ x: 0, y: 0 });

  return (
    <CursorContext.Provider value={cursorPosition}>
      <HugeAppLayout /> {/* hundreds of components underneath */}
    </CursorContext.Provider>
  );
}

// Every component that reads CursorContext re-renders on every mouse
// move, even ones that only occasionally care about cursorPosition.
function UnrelatedSidebarWidget() {
  const cursorPosition = useContext(CursorContext);
  // ...
}

